```javascript
async redirects() {
  const redirects = Object.entries(TRANSLATED_PATH).flatMap(
    ([key, localeObject]) => {
      return Object.entries(localeObject).map(
        ([locale, translatedPath]) => ({
          source: `/${locale}${key}`,
          destination: `/${locale}${translatedPath}`,
          permanent: false,
        })
      );
    }
  );
  return redirects;
}
```

