    @staticmethod
    def average_price(prices=None):
        if prices is None:
            return 0
        return sum(prices) / len(prices)

    @property
    def information(self):
        return f"Товар: {self.name}, розничная цена: {self.retail_price}, закупочная цена: {self.purchase_price}"

